<?php namespace App\Http\Controllers\Api\V1; use Illuminate\Http\Request; use App\Models\Attendance; class AttendanceController extends Controller {public function students(Request $r){$this->authorizeRole($r,['super_admin','admin','teacher']);$d=$r->validate(['date'=>'required|date','class_id'=>'required|integer','records'=>'required|array','records.*.student_id'=>'required|integer','records.*.status'=>'required|in:present,absent,late,leave']);foreach($d['records'] as $x)Attendance::updateOrCreate(['school_id'=>$r->user()->school_id,'student_id'=>$x['student_id'],'date'=>$d['date']],['class_id'=>$d['class_id'],'status'=>$x['status'],'marked_by'=>$r->user()->id]);return $this->ok(null,'Attendance saved');}public function studentHistory(Request $r){return $this->ok(Attendance::where('school_id',$r->user()->school_id)->whereNotNull('student_id')->when($r->student_id,fn($q)=>$q->where('student_id',$r->student_id))->orderByDesc('date')->paginate(50));}public function teachers(Request $r){$this->authorizeRole($r,['super_admin','admin']);$d=$r->validate(['date'=>'required|date','records'=>'required|array']);foreach($d['records'] as $x)Attendance::updateOrCreate(['school_id'=>$r->user()->school_id,'teacher_id'=>$x['teacher_id'],'date'=>$d['date']],['status'=>$x['status'],'marked_by'=>$r->user()->id]);return $this->ok(null,'Teacher attendance saved');}public function teacherHistory(Request $r){return $this->ok(Attendance::where('school_id',$r->user()->school_id)->whereNotNull('teacher_id')->orderByDesc('date')->paginate(50));}}
